    // sf=x|op=x|S=1|11010010|Rm=xxxxx|cond=xxxx|0|o2=0|Rn=xxxxx|o3=0|nzcv=xxxx
    let Rm: u8 = ((bits >> 16) & 0x1f) as u8;
    let cond: u8 = ((bits >> 12) & 0xf) as u8;
    let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
    let nzcv: u8 = (bits & 0xf) as u8;
