fn decode_rmif(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffe07c10 != 0xba000400 {
        return Err(DecodeError::Unallocated);
    }
    // sf=1|op=0|S=1|1|101|0000|imm6=xxxxxx|00001|Rn=xxxxx|o2=0|mask=xxxx
    if (bits & 0xe0000010) == 0xa0000000 {
        // RMIF  <Xn>, #<shift>, #<mask>
        let imm6: u8 = ((bits >> 15) & 0x3f) as u8;
        let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
        let mask: u8 = (bits & 0xf) as u8;
        Ok(Instruction::RmifOnlyRmif {
            Xn: Rn.into(),
            shift: imm6,
            mask,
        })
    } else {
        Err(DecodeError::Unallocated)
    }
}

fn decode_setf(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffffbc1f != 0x3a00080d {
        return Err(DecodeError::Unallocated);
    }
    // sf=0|op=0|S=1|11010000|opcode2=000000|sz=x|0010|Rn=xxxxx|o3=0|mask=1101
    let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
    match bits & 0xe01fc01f {
        0x2000000d => {
            // SETF8, SETF16 — SETF8
            // SETF8  <Wn>
            Ok(Instruction::Setf8OnlySetf { Wn: Rn.into() })
        }
        0x2000400d => {
            // SETF8, SETF16 — SETF16
            // SETF16  <Wn>
            Ok(Instruction::Setf16OnlySetf { Wn: Rn.into() })
        }
        _ => Err(DecodeError::Unallocated),
    }
}
